import{_ as a,o as n,c as o,a0 as t}from"./chunks/framework.CWG7uS0z.js";const h=JSON.parse('{"title":"智能体服务 (AI Agent)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai-agent.md","filePath":"guide/ai-agent.md"}'),s={name:"guide/ai-agent.md"};function r(i,e,l,d,c,g){return n(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="智能体服务-ai-agent" tabindex="-1">智能体服务 (AI Agent) <a class="header-anchor" href="#智能体服务-ai-agent" aria-label="Permalink to &quot;智能体服务 (AI Agent)&quot;">​</a></h1><p>在 Farmer Platform 中，我们引入了基于大语言模型（LLM）的智能体作为平台的“超级数据分析师”。该模块位于 <code>ai-agent/</code> 目录，利用了 <strong>Python 生态</strong> 的强大 AI 能力。</p><h2 id="_1-技术架构选型" tabindex="-1">1. 技术架构选型 <a class="header-anchor" href="#_1-技术架构选型" aria-label="Permalink to &quot;1. 技术架构选型&quot;">​</a></h2><ul><li><strong>运行环境</strong>: Python 3.10+</li><li><strong>Web 框架</strong>: <a href="https://fastapi.tiangolo.com/" target="_blank" rel="noreferrer">FastAPI</a> (异步高性能 Web 框架)</li><li><strong>LLM 引擎</strong>: <a href="https://api.deepseek.com" target="_blank" rel="noreferrer">DeepSeek API (V3 聊天模型)</a></li><li><strong>开发框架</strong>: <a href="https://python.langchain.com/docs/" target="_blank" rel="noreferrer">LangChain Python</a></li><li><strong>工具调用</strong>: 模块化 Engine 架构 (Modular Engine)</li><li><strong>通信协议</strong>: Server-Sent Events (SSE) 流式传输</li></ul><h2 id="_2-模块化-engine-架构" tabindex="-1">2. 模块化 Engine 架构 <a class="header-anchor" href="#_2-模块化-engine-架构" aria-label="Permalink to &quot;2. 模块化 Engine 架构&quot;">​</a></h2><p>为了保证 AI 能力的可扩展性，我们将所有的工具调用逻辑封装在 <code>engine/</code> 目录下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ai-agent/</span></span>
<span class="line"><span>├── main.py                   # FastAPI 入口与 SSE 路由</span></span>
<span class="line"><span>├── engine/                   # 核心智能体引擎</span></span>
<span class="line"><span>│   ├── __init__.py           # 工具聚合与导出</span></span>
<span class="line"><span>│   ├── context.py            # 请求上下文管理 (ContextVar)</span></span>
<span class="line"><span>│   ├── products/tools.py     # 商品查询工具</span></span>
<span class="line"><span>│   ├── orders/tools.py       # 异常订单分析工具</span></span>
<span class="line"><span>│   ├── dashboard/tools.py    # 数据大屏聚合工具</span></span>
<span class="line"><span>│   └── ...                   # 其他领域工具</span></span></code></pre></div><h3 id="_2-1-鉴权上下文传递-contextvar" tabindex="-1">2.1 鉴权上下文传递 (ContextVar) <a class="header-anchor" href="#_2-1-鉴权上下文传递-contextvar" aria-label="Permalink to &quot;2.1 鉴权上下文传递 (ContextVar)&quot;">​</a></h3><p>由于 Python 的 <code>httpx</code> 调用是异步的，为了确保 AI 调用后端接口时能携带当前管理员的身份（JWT Token），我们使用了 <code>contextvars.ContextVar</code>：</p><ol><li><code>main.py</code> 在接收到前端请求时，从 Header 中提取 Token 并存入 <code>request_token</code>。</li><li><code>engine/context.py</code> 中的 <code>get_headers()</code> 会自动从当前异步上下文中读取该 Token。</li><li>所有的 Tools 在调用后端接口时，都会自动携带该身份证明，确保数据访问安全。</li></ol><h2 id="_3-tool-calling-工具调用-机制" tabindex="-1">3. Tool Calling (工具调用) 机制 <a class="header-anchor" href="#_3-tool-calling-工具调用-机制" aria-label="Permalink to &quot;3. Tool Calling (工具调用) 机制&quot;">​</a></h2><p>通过 LangChain 的 <code>bind_tools</code> 功能，AI 具备了“感知并调用”后端接口的能力：</p><ol><li><strong>工具声明</strong>: 每一个 Python 函数都通过 <code>@tool</code> 装饰器或 <code>BaseTool</code> 子类进行定义，并配有详尽的中文描述。</li><li><strong>意图决策</strong>: DeepSeek-V3 接收到用户问题后，会自动判断是否需要调用某个工具。</li><li><strong>异步执行</strong>: LangChain 拦截到决策后，通过 <code>ainvoke</code> 异步调用后端 Spring Boot API。</li><li><strong>数据汇聚</strong>: 工具返回的 JSON 数据被注入到 LLM 的上下文中，作为其分析的“客观事实”。</li></ol><h2 id="_4-极致安全-safe-summary-mode" tabindex="-1">4. 极致安全：Safe Summary Mode <a class="header-anchor" href="#_4-极致安全-safe-summary-mode" aria-label="Permalink to &quot;4. 极致安全：Safe Summary Mode&quot;">​</a></h2><p>为了保证输出内容的纯净度和专业性，系统实施了 <strong>Safe Summary Mode (安全总结模式)</strong>：</p><ol><li><strong>第一阶段 (Action)</strong>: AI 自由思考并触发多次工具调用，收集原始业务数据。</li><li><strong>第二阶段 (Refine)</strong>: <strong>丢弃并重置</strong>所有中间的工具调用记录（屏蔽 XML 标签和函数名）。</li><li><strong>第三阶段 (Summary)</strong>: 使用一个全新的、受限的 Prompt 引导 AI 对收集到的原始 JSON 数据进行总结。 <ul><li><strong>输出要求</strong>: 3-4 个要点，200 字以内。</li><li><strong>内容要求</strong>: 直接给出业务洞察与行动建议。</li></ul></li></ol><h2 id="_5-sse-前端集成-streaming" tabindex="-1">5. SSE 前端集成 (Streaming) <a class="header-anchor" href="#_5-sse-前端集成-streaming" aria-label="Permalink to &quot;5. SSE 前端集成 (Streaming)&quot;">​</a></h2><p>FastAPI 通过 <code>StreamingResponse</code> 与前端 Vue 3 实现无缝流式对接：</p><ul><li><strong>服务端</strong>: 实时迭代 <code>streaming_llm.astream()</code> 生成的内容，并通过 JSON 序列化推送到 SSE 通道。</li><li><strong>数据清洗</strong>: 在 <code>main.py</code> 中通过 <code>sanitize_content</code> 正则表达式过滤掉可能残留的 AI 内部指令标签，确保前端用户看到的只有纯净的文字。</li><li><strong>前端</strong>: 使用 <code>ReadableStream</code> 进行逐字渲染，实现极致的交互体验。</li></ul>`,19)])])}const m=a(s,[["render",r]]);export{h as __pageData,m as default};
